// ============================================================================
// Path Utilities
// ============================================================================

// Convert operator ID to Theatre.js object name format
// "/my-operator" -> "my-operator", "/container/nested" -> "container / nested"
export function opIdToObjectName(opId: string): string {
  return opId.slice(1).split('/').join(' / ')
}

// Build the field path for timeline track
// Uses Theatre.js format: "objectName / fieldName / subField"
export function getFieldPath(opId: string, fieldName: string, subPath?: string[]): string {
  const objectName = opIdToObjectName(opId)
  const parts = [objectName, fieldName, ...(subPath || [])]
  return parts.join(' / ')
}

// Parse a track ID and return the corresponding operator and field
// Returns null if operator/field not found
export function getFieldFromTrackPath(fieldPath: string): {
  operator: Operator<IOperator>
  fieldName: string
  subPath?: string[]
  field: AnyField
} | null {
  const parts = fieldPath.split(' / ')
  if (parts.length < 2) return null

  // Reconstruct operator ID by trying each split point
  // "container / nested / fieldName" → try "/container/nested", then "/container"
  let operator: Operator<IOperator> | null = null
  let opPartCount = 0

  for (let i = parts.length - 2; i >= 0; i--) {
    const opId = `/${parts.slice(0, i + 1).join('/')}`
    operator = getOp(opId)
    if (operator) {
      opPartCount = i + 1
      break
    }
  }

  const field = op.inputs[fieldName]
  // Check if field has a non-default value - warn before losing data
  if (field && hasNonDefaultValue(field)) {
    setPendingHideField(fieldName)
    return
  }
  hideField(op, fieldName)
}

