1	// Bezier interpolation engine for the native timeline system
2	// Provides keyframe evaluation with cubic bezier easing
3	
4	import type {
5	  BezierHandles,
6	  Keyframe,
7	  KeyframeValue,
8	  Point2D,
9	  Point3D,
10	  RGBA,
11	  Track,
12	  Vec2,
13	  Vec3,
14	} from './types'
15	import { DEFAULT_BEZIER_HANDLES } from './types'
16	
17	// ============================================================================
18	// Core Bezier Math
19	// ============================================================================
20	
21	// Evaluate a cubic bezier curve at parameter t
22	// B(t) = (1-t)^3 * P0 + 3*(1-t)^2 * t * P1 + 3*(1-t) * t^2 * P2 + t^3 * P3
23	export function evaluateCubicBezier(
24	  t: number,
25	  p0: number,
26	  p1: number,
27	  p2: number,
28	  p3: number
29	): number {
30	  const oneMinusT = 1 - t
31	  const oneMinusTSquared = oneMinusT * oneMinusT
32	  const oneMinusTCubed = oneMinusTSquared * oneMinusT
33	  const tSquared = t * t
34	  const tCubed = tSquared * t
35	
36	  return (
37	    oneMinusTCubed * p0 +
38	    3 * oneMinusTSquared * t * p1 +
39	    3 * oneMinusT * tSquared * p2 +
40	    tCubed * p3
41	  )
42	}
43	
44	// Evaluate the derivative of a cubic bezier curve at parameter t
45	// B'(t) = 3*(1-t)^2 * (P1-P0) + 6*(1-t)*t * (P2-P1) + 3*t^2 * (P3-P2)
46	function evaluateCubicBezierDerivative(
47	  t: number,
48	  p0: number,
49	  p1: number,
50	  p2: number,
51	  p3: number
52	): number {
53	  const oneMinusT = 1 - t
54	  const oneMinusTSquared = oneMinusT * oneMinusT
55	  const tSquared = t * t
56	
57	  return 3 * oneMinusTSquared * (p1 - p0) + 6 * oneMinusT * t * (p2 - p1) + 3 * tSquared * (p3 - p2)
58	}
59	
60	// Find the parameter t for a given x value using Newton-Raphson iteration
61	// This maps time (x) to bezier parameter (t)
62	// x: The x value to find t for (normalized 0-1)
63	// x1, x2: Control point x values (from cubic-bezier)
64	// epsilon: Precision threshold (default: 0.0001)
65	// maxIterations: Maximum Newton-Raphson iterations (default: 8)
66	export function findTForX(
67	  x: number,
68	  x1: number,
69	  x2: number,
70	  epsilon = 0.0001,
71	  maxIterations = 8
72	): number {
73	  // Edge cases
74	  if (x <= 0) return 0
75	  if (x >= 1) return 1
76	
77	  // For linear curves, t = x
78	  if (x1 === 0 && x2 === 1) return x
79	
80	  // Initial guess using linear approximation
81	  let t = x
82	
83	  // Newton-Raphson iteration
84	  for (let i = 0; i < maxIterations; i++) {
85	    const currentX = evaluateCubicBezier(t, 0, x1, x2, 1)
86	    const error = currentX - x
87	
88	    if (Math.abs(error) < epsilon) {
89	      return t
90	    }
91	
92	    const derivative = evaluateCubicBezierDerivative(t, 0, x1, x2, 1)
93	
94	    // Avoid division by zero
95	    if (Math.abs(derivative) < 1e-10) {
96	      break
97	    }
98	
99	    t = t - error / derivative
100	
101	    // Clamp to valid range
102	    t = Math.max(0, Math.min(1, t))
103	  }
104	
105	  // Fallback to binary search if Newton-Raphson doesn't converge
106	  let low = 0
107	  let high = 1
108	  t = x
109	
110	  while (high - low > epsilon) {
111	    const currentX = evaluateCubicBezier(t, 0, x1, x2, 1)
112	
113	    if (currentX < x) {
114	      low = t
115	    } else {
116	      high = t
117	    }
118	
119	    t = (low + high) / 2
120	  }
121	
122	  return t
123	}
124	
125	// Evaluate a bezier easing curve at normalized time x, returns the eased value y
126	// x: Normalized time (0-1)
127	// handles: Bezier control point handles
128	export function evaluateBezierEasing(x: number, handles: BezierHandles): number {
129	  // Edge cases
130	  if (x <= 0) return 0
131	  if (x >= 1) return 1
132	
133	  // Find t for the given x
134	  const t = findTForX(x, handles.left[0], handles.right[0])
135	
136	  // Evaluate y at t
137	  return evaluateCubicBezier(t, 0, handles.left[1], handles.right[1], 1)
138	}
139	
140	// ============================================================================
141	// Type-Specific Interpolation
142	// ============================================================================
143	
144	export function interpolateNumber(v1: number, v2: number, t: number): number {
145	  return v1 + (v2 - v1) * t
146	}
147	
148	export function interpolateColor(c1: RGBA, c2: RGBA, t: number): RGBA {
149	  return {
150	    r: interpolateNumber(c1.r, c2.r, t),
151	    g: interpolateNumber(c1.g, c2.g, t),
152	    b: interpolateNumber(c1.b, c2.b, t),
153	    a: interpolateNumber(c1.a, c2.a, t),
154	  }
155	}
156	
157	export function interpolateVec2(v1: Vec2, v2: Vec2, t: number): Vec2 {
158	  return {
159	    x: interpolateNumber(v1.x, v2.x, t),
160	    y: interpolateNumber(v1.y, v2.y, t),
161	  }
162	}
163	
164	export function interpolateVec3(v1: Vec3, v2: Vec3, t: number): Vec3 {
165	  return {
166	    x: interpolateNumber(v1.x, v2.x, t),
167	    y: interpolateNumber(v1.y, v2.y, t),
168	    z: interpolateNumber(v1.z, v2.z, t),
169	  }
170	}
171	
172	export function interpolatePoint2D(p1: Point2D, p2: Point2D, t: number): Point2D {
173	  return {
174	    lng: interpolateNumber(p1.lng, p2.lng, t),
175	    lat: interpolateNumber(p1.lat, p2.lat, t),
176	  }
177	}
178	
179	export function interpolatePoint3D(p1: Point3D, p2: Point3D, t: number): Point3D {
180	  return {
181	    lng: interpolateNumber(p1.lng, p2.lng, t),
182	    lat: interpolateNumber(p1.lat, p2.lat, t),
183	    alt: interpolateNumber(p1.alt, p2.alt, t),
184	  }
185	}
186	
187	// Interpolate compound (object) values recursively
188	export function interpolateCompound(
189	  v1: Record<string, KeyframeValue>,
190	  v2: Record<string, KeyframeValue>,
191	  t: number
192	): Record<string, KeyframeValue> {
193	  const result: Record<string, KeyframeValue> = {}
194	
195	  for (const key of Object.keys(v1)) {
196	    if (!(key in v2)) {
197	      result[key] = v1[key]
198	      continue
199	    }
200	
201	    result[key] = interpolateValue(v1[key], v2[key], t)
202	  }
203	
204	  return result
205	}
206	
207	// Interpolate any keyframe value based on its type
208	export function interpolateValue(v1: KeyframeValue, v2: KeyframeValue, t: number): KeyframeValue {
209	  // Boolean and string: no interpolation (step)
210	  if (typeof v1 === 'boolean' || typeof v1 === 'string') {
211	    return t < 0.5 ? v1 : v2
212	  }
213	
214	  // Number
215	  if (typeof v1 === 'number' && typeof v2 === 'number') {
216	    return interpolateNumber(v1, v2, t)
217	  }
218	
219	  // Objects
220	  if (typeof v1 === 'object' && typeof v2 === 'object' && v1 !== null && v2 !== null) {
221	    // RGBA color
222	    if ('r' in v1 && 'g' in v1 && 'b' in v1 && 'a' in v1) {
223	      return interpolateColor(v1 as RGBA, v2 as RGBA, t)
224	    }
225	
226	    // Point3D (check alt before Point2D since Point3D has lng/lat too)
227	    if ('lng' in v1 && 'lat' in v1 && 'alt' in v1) {
228	      return interpolatePoint3D(v1 as Point3D, v2 as Point3D, t)
229	    }
230	
231	    // Point2D
232	    if ('lng' in v1 && 'lat' in v1) {
233	      return interpolatePoint2D(v1 as Point2D, v2 as Point2D, t)
234	    }
235	
236	    // Vec3 (check z before Vec2)
237	    if ('x' in v1 && 'y' in v1 && 'z' in v1) {
238	      return interpolateVec3(v1 as Vec3, v2 as Vec3, t)
239	    }
240	
241	    // Vec2
242	    if ('x' in v1 && 'y' in v1) {
243	      return interpolateVec2(v1 as Vec2, v2 as Vec2, t)
244	    }
245	
246	    // Generic compound object
247	    return interpolateCompound(
248	      v1 as Record<string, KeyframeValue>,
249	      v2 as Record<string, KeyframeValue>,
250	      t
251	    )
252	  }
253	
254	  // Fallback: return v1 at t<0.5, v2 otherwise
255	  return t < 0.5 ? v1 : v2
256	}
257	
258	// ============================================================================
259	// Keyframe Interpolation
260	// ============================================================================
261	
262	// Interpolate between two keyframes at a given time
263	// time: The current time in seconds
264	// k1: The keyframe before or at time
265	// k2: The keyframe after time
266	export function interpolateBetweenKeyframes(
267	  time: number,
268	  k1: Keyframe,
269	  k2: Keyframe
270	): KeyframeValue {
271	  // If same position or before k1, return k1 value
272	  if (time <= k1.position || k1.position === k2.position) {
273	    return k1.value
274	  }
275	
276	  // If at or after k2, return k2 value
277	  if (time >= k2.position) {
278	    return k2.value
279	  }
280	
281	  // Hold interpolation: step function
282	  if (k1.interpolation === 'hold') {
283	    return k1.value
284	  }
285	
286	  // Calculate normalized time between keyframes
287	  const normalizedTime = (time - k1.position) / (k2.position - k1.position)
288	
289	  // Linear interpolation
290	  if (k1.interpolation === 'linear') {
291	    return interpolateValue(k1.value, k2.value, normalizedTime)
292	  }
293	
294	  // Bezier interpolation
295	  const handles = k1.handles || DEFAULT_BEZIER_HANDLES
296	  const easedTime = evaluateBezierEasing(normalizedTime, handles)
297	  return interpolateValue(k1.value, k2.value, easedTime)
298	}
299	
300	// ============================================================================
301	// Track Evaluation
302	// ============================================================================
303	
304	// Binary search to find the surrounding keyframes for a given time
305	// Returns the keyframes immediately before and after the time
306	// keyframes: Sorted array of keyframes
307	// time: The time to search for
308	export function findSurroundingKeyframes(
309	  keyframes: Keyframe[],
310	  time: number
311	): { left: Keyframe | null; right: Keyframe | null } {
312	  if (keyframes.length === 0) {
313	    return { left: null, right: null }
314	  }
315	
316	  if (keyframes.length === 1) {
317	    const kf = keyframes[0]
318	    if (time <= kf.position) {
319	      return { left: null, right: kf }
320	    }
321	    return { left: kf, right: null }
322	  }
323	
324	  // Binary search
325	  let low = 0
326	  let high = keyframes.length - 1
327	
328	  // Check edges
329	  if (time <= keyframes[low].position) {
330	    return { left: null, right: keyframes[low] }
331	  }
332	  if (time >= keyframes[high].position) {
333	    return { left: keyframes[high], right: null }
334	  }
335	
336	  // Binary search for the surrounding keyframes
337	  while (low <= high) {
338	    const mid = Math.floor((low + high) / 2)
339	    const kf = keyframes[mid]
340	
341	    if (time === kf.position) {
342	      // Exact match - this keyframe is both left and right
343	      return {
344	        left: kf,
345	        right: mid < keyframes.length - 1 ? keyframes[mid + 1] : null,
346	      }
347	    }
348	
349	    if (time < kf.position) {
350	      // Check if this is the right keyframe we're looking for
351	      if (mid > 0 && keyframes[mid - 1].position < time) {
352	        return { left: keyframes[mid - 1], right: kf }
353	      }
354	      high = mid - 1
355	    } else {
356	      // Check if this is the left keyframe we're looking for
357	      if (mid < keyframes.length - 1 && keyframes[mid + 1].position > time) {
358	        return { left: kf, right: keyframes[mid + 1] }
359	      }
360	      low = mid + 1
361	    }
362	  }
363	
364	  // Shouldn't reach here, but return safe default
365	  return { left: keyframes[low - 1] || null, right: keyframes[low] || null }
366	}
367	
368	// Evaluate a track at a given time
369	// track: The track to evaluate
370	// time: The current time in seconds
371	// Returns the interpolated value, or undefined if track has no keyframes
372	export function evaluateTrack(track: Track, time: number): KeyframeValue | undefined {
373	  const { keyframes } = track
374	
375	  if (keyframes.length === 0) {
376	    return undefined
377	  }
378	
379	  const { left, right } = findSurroundingKeyframes(keyframes, time)
